/**
 * Generated by `pnpm theme:generate`. Do not edit.
 *
 * The baseline theme, as the Worker sees it: normalised name to source. The
 * keys are the complete set of templates the admin may edit -- an override
 * cannot introduce a name the theme does not ship, which is what makes the
 * whitelist check a memory lookup rather than a prefix test.
 */

export const BASELINE: Record<string, string> = {
  "layouts/base": "<!doctype html>\n<html lang=\"{{ site.language | default: 'en' }}\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    {% comment %}\n      One scheme, declared: the theme is light, and this is what tells the browser\n      to draw form controls, scrollbars and the canvas to match. It used to declare\n      both and follow the reader's system, which turned every page black for anyone\n      in dark mode -- a palette nobody had designed.\n    {% endcomment %}\n    <meta name=\"color-scheme\" content=\"light\">\n    {% render 'snippets/seo-meta', seo: seo, page: page, site: site, content: content %}\n    <link rel=\"stylesheet\" href=\"{{ 'theme.css' | asset_url }}\">\n  </head>\n  <body>\n    {% comment %}\n      First in the document, because its whole point is to be the first thing a\n      keyboard user can reach. Hidden until it has focus.\n    {% endcomment %}\n    <a class=\"visually-hidden\" href=\"#main\">Skip to content</a>\n    {% render 'snippets/header', site: site %}\n    <main id=\"main\">\n      {% block %}{% endblock %}\n    </main>\n    {% render 'snippets/footer', site: site %}\n    {% render 'snippets/cookie-consent', site: site %}\n  </body>\n</html>\n",
  "snippets/category-nav": "{% comment %}\n  The categories a page's content type can be filed under, as a sidebar.\n\n  Filtered here rather than by the platform, because one `site.taxonomy` serves both\n  the post list and the product list: a page passes the type it is about and gets the\n  vocabularies that name it. Nothing renders when none do, which is what lets the\n  layout fall back to one column.\n{% endcomment %}\n{% assign matching = false %}\n{% for group in site.taxonomy %}\n  {% if group.content_types contains type %}{% assign matching = true %}{% endif %}\n{% endfor %}\n\n{% if matching %}\n  <nav class=\"category-nav\" aria-label=\"Categories\">\n    {% for group in site.taxonomy %}\n      {% if group.content_types contains type %}\n        <div class=\"category-group\">\n          <p class=\"category-group-name\">{{ group.name }}</p>\n          <ul>\n            {% for term in group.terms %}\n              <li><a href=\"{{ term.url | url }}\">{{ term.name }}</a></li>\n            {% endfor %}\n          </ul>\n        </div>\n      {% endif %}\n    {% endfor %}\n  </nav>\n{% endif %}\n",
  "snippets/cookie-consent": "{% if site.settings.cookie_notice %}\n  <div class=\"cookie-consent\" role=\"status\" hidden data-cookie-consent>\n    <p>{{ site.settings.cookie_notice }}</p>\n    <button type=\"button\" data-cookie-consent-accept>Got it</button>\n  </div>\n  <script src=\"{{ 'theme.js' | asset_url }}\" defer></script>\n{% endif %}\n",
  "snippets/footer": "<footer class=\"site-footer\">\n  {% if site.settings.footer %}<p>{{ site.settings.footer }}</p>{% endif %}\n  {% if site.settings.social_links.size > 0 %}\n    <ul class=\"social\">\n      {% for link in site.settings.social_links %}\n        <li><a href=\"{{ link.href }}\">{{ link.label }}</a></li>\n      {% endfor %}\n    </ul>\n  {% endif %}\n  {% comment %}\n    Present unless the site bought a white-label licence, in which case the platform\n    leaves it out of the context altogether. The marker attribute is what tells the\n    platform this theme rendered it; see `injectAttribution` in @typeky/core.\n  {% endcomment %}\n  {% if site.attribution %}\n    <p class=\"attribution\">\n      <a href=\"{{ site.attribution.url }}\" rel=\"noopener\" data-typeky-attribution>{{ site.attribution.text }}</a>\n    </p>\n  {% endif %}\n</footer>\n",
  "snippets/header": "<header class=\"site-header\">\n  <a class=\"brand\" href=\"{{ '/' | url }}\">\n    {% if site.logo_url %}<img src=\"{{ site.logo_url }}\" alt=\"{{ site.name }}\">{% else %}{{ site.name }}{% endif %}\n  </a>\n  <nav aria-label=\"Main\">\n    <ul>\n      {% for item in site.nav %}\n        <li><a href=\"{{ item.href | url }}\">{{ item.label }}</a></li>\n      {% endfor %}\n    </ul>\n  </nav>\n</header>\n",
  "snippets/pagination": "{% if page.pagination %}\n  <nav class=\"pagination\" aria-label=\"Pagination\">\n    {% if page.pagination.previous_url %}\n      <a rel=\"prev\" href=\"{{ page.pagination.previous_url | url }}\">Newer</a>\n    {% endif %}\n    <span>{{ page.pagination.page }} / {{ page.pagination.pages }}</span>\n    {% if page.pagination.next_url %}\n      <a rel=\"next\" href=\"{{ page.pagination.next_url | url }}\">Older</a>\n    {% endif %}\n  </nav>\n{% endif %}\n",
  "snippets/post-card": "{% comment %}\n  One row of the post list. `post` is what the caller passes: a summary, not the\n  whole document -- a list renders titles and summaries, and the bodies of ten\n  posts would be a page's context with ten posts' worth of JSON nothing reads.\n{% endcomment %}\n<article class=\"card\">\n  {% if post.cover_url %}\n    <a class=\"card-cover\" href=\"{{ post.url | url }}\">\n      <img src=\"{{ post.cover_url }}\" alt=\"{{ post.title }}\">\n    </a>\n  {% endif %}\n\n  {% comment %}\n    The text is wrapped so the stylesheet can give the card a border and a clipped\n    cover without also padding the image: the body carries the padding, the cover\n    runs to the edge.\n  {% endcomment %}\n  <div class=\"card-body\">\n    <h2><a href=\"{{ post.url | url }}\">{{ post.title }}</a></h2>\n\n    <p class=\"meta\">\n      {% if post.published_at %}\n        <time datetime=\"{{ post.published_at }}\">{{ post.published_at | date: site.date_format, site.timezone }}</time>\n      {% endif %}\n      {% for term in post.terms %}<a class=\"term\" title=\"{{ term.vocabulary }}\" href=\"{{ term.url | url }}\">{{ term.name }}</a>{% endfor %}\n    </p>\n\n    {% if post.excerpt %}<p class=\"excerpt\">{{ post.excerpt }}</p>{% endif %}\n  </div>\n</article>\n",
  "snippets/product-card": "{% comment %}\n  One row of the product list. `product` is what the caller passes: a summary,\n  so the card renders what a summary carries -- no body, no specs.\n{% endcomment %}\n<article class=\"card product-card\">\n  {% if product.cover_url %}\n    <a class=\"card-cover\" href=\"{{ product.url | url }}\">\n      <img src=\"{{ product.cover_url }}\" alt=\"{{ product.title }}\">\n    </a>\n  {% endif %}\n\n  <div class=\"card-body\">\n    <h2><a href=\"{{ product.url | url }}\">{{ product.title }}</a></h2>\n\n    {% if product.price_label %}<p class=\"price\">{{ product.price_label }}</p>{% endif %}\n    {% if product.terms %}\n      <p class=\"meta\">\n        {% comment %} The vocabulary rides on the chip, as on a post. {% endcomment %}\n        {% for term in product.terms %}<a class=\"term\" title=\"{{ term.vocabulary }}\" href=\"{{ term.url | url }}\">{{ term.name }}</a>{% endfor %}\n      </p>\n    {% endif %}\n    {% if product.excerpt %}<p class=\"excerpt\">{{ product.excerpt }}</p>{% endif %}\n  </div>\n</article>\n",
  "snippets/seo-meta": "{% comment %}\n  Everything a crawler or a chat client reads about this page.\n\n  The values are computed by the platform -- the absolute canonical URL, the\n  resolved social image -- and this only prints them. `content` is passed because\n  one post property is worth emitting; on a list it is an array, and the `and`\n  below is what keeps that from mattering.\n{% endcomment %}\n<title>{{ seo.document_title }}</title>\n{% comment %}\n  The browser tab icon, when the site has one. `apple-touch-icon` is the same file:\n  iOS wants a larger square than a favicon, and a site with one image has one image.\n{% endcomment %}\n{% if site.favicon_url %}\n  <link rel=\"icon\" href=\"{{ site.favicon_url }}\">\n  <link rel=\"apple-touch-icon\" href=\"{{ site.favicon_url }}\">\n{% endif %}\n{% if seo.description %}<meta name=\"description\" content=\"{{ seo.description }}\">{% endif %}\n{% if page.canonical %}<link rel=\"canonical\" href=\"{{ page.canonical }}\">{% endif %}\n\n<meta property=\"og:type\" content=\"{% if page.kind == 'post' %}article{% else %}website{% endif %}\">\n<meta property=\"og:title\" content=\"{{ seo.title }}\">\n{% if seo.description %}<meta property=\"og:description\" content=\"{{ seo.description }}\">{% endif %}\n{% if page.canonical %}<meta property=\"og:url\" content=\"{{ page.canonical }}\">{% endif %}\n<meta property=\"og:site_name\" content=\"{{ site.name }}\">\n{% if seo.og_image %}<meta property=\"og:image\" content=\"{{ seo.og_image }}\">{% endif %}\n{% if page.kind == 'post' and content.published_at %}\n  <meta property=\"article:published_time\" content=\"{{ content.published_at }}\">\n{% endif %}\n\n{% comment %} The same again for the network with its own vocabulary. {% endcomment %}\n<meta name=\"twitter:card\" content=\"{% if seo.og_image %}summary_large_image{% else %}summary{% endif %}\">\n<meta name=\"twitter:title\" content=\"{{ seo.title }}\">\n{% if seo.description %}<meta name=\"twitter:description\" content=\"{{ seo.description }}\">{% endif %}\n{% if seo.og_image %}<meta name=\"twitter:image\" content=\"{{ seo.og_image }}\">{% endif %}\n\n{% if seo.json_ld %}<script type=\"application/ld+json\">{{ seo.json_ld | json_ld }}</script>{% endif %}\n",
  "templates/404": "{% layout 'layouts/base' %}\n<article class=\"not-found\">\n  <h1>Page not found</h1>\n  <p>That address does not exist on this site. It may have been moved, or the link that brought you here may be wrong.</p>\n  <p><a href=\"{{ '/' | url }}\">Back to {{ site.name }}</a></p>\n</article>\n",
  "templates/home": "{% layout 'layouts/base' %}\n{% comment %}\n  The home page: whichever page is flagged is_home.\n\n  It opens with a hero built from the site's own name and tagline -- the two things\n  a first-time visitor is here to find out -- then the page's own blocks, and then\n  the newest posts and products the platform hands it. Those two sections are how a\n  visitor reaches a site whose home page the operator has not filled in yet, and\n  neither renders when there is nothing to show.\n\n  The heading is the site's name rather than the page's title on purpose: a home\n  page is usually titled after what it is (\"Home\"), while the site's name is what\n  the page is *about*. The title still reaches `<title>` and the share card, which\n  is where a title does its work.\n{% endcomment %}\n<section class=\"hero\">\n  <h1>{{ site.name }}</h1>\n  {% if site.tagline %}<p class=\"lead\">{{ site.tagline }}</p>{% endif %}\n  <p class=\"hero-actions\">\n    <a class=\"button\" href=\"{{ '/posts' | url }}\">Read the blog</a>\n    <a class=\"button secondary\" href=\"{{ '/products' | url }}\">Shop</a>\n  </p>\n</section>\n\n<article class=\"prose\">\n  {{ content.blocks | render_blocks }}\n</article>\n\n{% if content.latest_posts.size > 0 %}\n  <section class=\"section\">\n    <div class=\"section-head\">\n      <h2>Latest posts</h2>\n      <a class=\"section-more\" href=\"{{ '/posts' | url }}\">All posts</a>\n    </div>\n    <ul class=\"post-list\">\n      {% for post in content.latest_posts %}\n        <li>{% render 'snippets/post-card', post: post, site: site %}</li>\n      {% endfor %}\n    </ul>\n  </section>\n{% endif %}\n\n{% if content.latest_products.size > 0 %}\n  <section class=\"section\">\n    <div class=\"section-head\">\n      <h2>Latest products</h2>\n      <a class=\"section-more\" href=\"{{ '/products' | url }}\">All products</a>\n    </div>\n    <ul class=\"product-list\">\n      {% for product in content.latest_products %}\n        <li>{% render 'snippets/product-card', product: product %}</li>\n      {% endfor %}\n    </ul>\n  </section>\n{% endif %}\n",
  "templates/page": "{% layout 'layouts/base' %}\n<article class=\"prose\">\n  <h1>{{ content.title }}</h1>\n  {{ content.blocks | render_blocks }}\n</article>\n",
  "templates/post": "{% layout 'layouts/base' %}\n<article class=\"prose\">\n  <header class=\"post-header\">\n    <h1>{{ content.title }}</h1>\n    {% comment %}\n      The excerpt is the summary the operator wrote for lists, shown here as the\n      standfirst: what a reader skims before deciding to read on, which is the same\n      job it does on a card.\n    {% endcomment %}\n    {% if content.excerpt %}<p class=\"lead\">{{ content.excerpt }}</p>{% endif %}\n    <p class=\"meta\">\n      {% if content.published_at %}\n        <time datetime=\"{{ content.published_at }}\">{{ content.published_at | date: site.date_format, site.timezone }}</time>\n      {% endif %}\n      {% comment %}\n        The edited time, shown only when it differs from the published one: an\n        \"updated\" that repeats the date beside it is noise, and one that differs is\n        the fact worth stating.\n      {% endcomment %}\n      {% if content.updated_at and content.updated_at != content.published_at %}\n        <span>Updated <time datetime=\"{{ content.updated_at }}\">{{ content.updated_at | date: site.date_format, site.timezone }}</time></span>\n      {% endif %}\n      {% comment %}\n        The vocabulary is on the chip as a tooltip rather than printed: a site that\n        keeps one vocabulary would otherwise repeat its name on every chip.\n      {% endcomment %}\n      {% for term in content.terms %}<a class=\"term\" title=\"{{ term.vocabulary }}\" href=\"{{ term.url | url }}\">{{ term.name }}</a>{% endfor %}\n    </p>\n  </header>\n\n  {% if content.cover_url %}\n    <img class=\"cover\" src=\"{{ content.cover_url }}\" alt=\"{{ content.title }}\">\n  {% endif %}\n\n  {{ content.blocks | render_blocks }}\n\n  {% if content.tags.size > 0 %}\n    <ul class=\"tags\" aria-label=\"Tags\">\n      {% for tag in content.tags %}<li>{{ tag }}</li>{% endfor %}\n    </ul>\n  {% endif %}\n</article>\n",
  "templates/posts": "{% layout 'layouts/base' %}\n{% comment %}\n  The post list, with the post categories in a sidebar. The sidebar is the same\n  snippet the product list uses, given `post`; it renders nothing when the site\n  keeps no post categories, and the layout falls back to one column.\n{% endcomment %}\n<div class=\"list-layout\">\n  <div class=\"list-main\">\n    <header class=\"list-header\">\n      <h1>{{ page.title | default: 'Posts' }}</h1>\n    </header>\n\n    <ul class=\"post-list\">\n      {% for post in content %}\n        <li>{% render 'snippets/post-card', post: post, site: site %}</li>\n      {% else %}\n        {% comment %}\n          `for ... else` rather than a length check: with an empty list there is\n          nothing to count, and this reads as what it is.\n        {% endcomment %}\n        <li class=\"empty\">Nothing has been published yet.</li>\n      {% endfor %}\n    </ul>\n\n    {% render 'snippets/pagination', page: page %}\n  </div>\n\n  <aside class=\"list-side\">\n    {% render 'snippets/category-nav', site: site, type: 'post' %}\n  </aside>\n</div>\n",
  "templates/product": "{% layout 'layouts/base' %}\n<article class=\"product\">\n  <header class=\"product-header\">\n    <h1>{{ content.title }}</h1>\n    {% comment %}\n      The summary the operator wrote, shown as the standfirst -- the same field the\n      list cards use, so the description does not change between the list and the\n      page it links to.\n    {% endcomment %}\n    {% if content.excerpt %}<p class=\"lead\">{{ content.excerpt }}</p>{% endif %}\n    {% comment %}\n      The terms this product is filed under, beside the price. A product can carry\n      more than one, so this iterates rather than printing a single value.\n    {% endcomment %}\n    {% if content.terms.size > 0 %}\n      <p class=\"meta\">\n        {% for term in content.terms %}<a class=\"term\" title=\"{{ term.vocabulary }}\" href=\"{{ term.url | url }}\">{{ term.name }}</a>{% endfor %}\n      </p>\n    {% endif %}\n    {% if content.price_label %}<p class=\"price\">{{ content.price_label }}</p>{% endif %}\n  </header>\n\n  {% if content.cover_url %}\n    <img class=\"cover\" src=\"{{ content.cover_url }}\" alt=\"{{ content.title }}\">\n  {% endif %}\n\n  {% comment %}\n    The gallery holds media ids the platform has already resolved to URLs. A\n    theme never sees an id it would have to look up, and never a storage key.\n  {% endcomment %}\n  {% if content.gallery.size > 0 %}\n    <ul class=\"gallery\">\n      {% for image in content.gallery %}\n        <li><img src=\"{{ image }}\" alt=\"{{ content.title }}\"></li>\n      {% endfor %}\n    </ul>\n  {% endif %}\n\n  {{ content.blocks | render_blocks }}\n\n  {% if content.specs.size > 0 %}\n    <dl class=\"specs\">\n      {% for spec in content.specs %}\n        <dt>{{ spec.label }}</dt><dd>{{ spec.value }}</dd>\n      {% endfor %}\n    </dl>\n  {% endif %}\n\n  {% if content.cta_url %}\n    {% comment %}\n      The button leaves the site -- there is no checkout here, on purpose. `rel`\n      keeps the destination from reaching back through the window it opened.\n\n      The hint is for a screen reader, which cannot see a new tab appear. It is\n      hidden by the stylesheet, which is why it arrived with one and not before:\n      written earlier it was visible to everybody, as a sentence no sighted\n      reader wants.\n    {% endcomment %}\n    <p class=\"cta\">\n      <a href=\"{{ content.cta_url }}\" rel=\"noopener noreferrer\" target=\"_blank\">{{ content.cta_label | default: 'Learn more' }}<span class=\"visually-hidden\"> (opens in a new tab)</span></a>\n    </p>\n  {% endif %}\n</article>\n",
  "templates/products": "{% layout 'layouts/base' %}\n{% comment %}\n  The product list, with the product categories in a sidebar. The same snippet the\n  post list uses, given `product`.\n{% endcomment %}\n<div class=\"list-layout\">\n  <div class=\"list-main\">\n    <header class=\"list-header\">\n      <h1>{{ page.title | default: 'Products' }}</h1>\n    </header>\n\n    <ul class=\"product-list\">\n      {% for product in content %}\n        <li>{% render 'snippets/product-card', product: product %}</li>\n      {% else %}\n        <li class=\"empty\">No products have been published yet.</li>\n      {% endfor %}\n    </ul>\n\n    {% render 'snippets/pagination', page: page %}\n  </div>\n\n  <aside class=\"list-side\">\n    {% render 'snippets/category-nav', site: site, type: 'product' %}\n  </aside>\n</div>\n",
  "templates/term": "{% layout 'layouts/base' %}\n{% comment %}\n  A term's archive: everything published under one term, newest first.\n\n  A term can carry posts and products at once, so each row picks the card that\n  matches what the summary actually has -- a product summary has a price and a\n  post's does not. The description is the term's own words, or the vocabulary's\n  when the term has none.\n{% endcomment %}\n<header class=\"list-header\">\n  <h1>{{ page.title }}</h1>\n</header>\n\n{% if page.description %}<p class=\"lead\">{{ page.description }}</p>{% endif %}\n\n<ul class=\"post-list\">\n  {% for item in content %}\n    <li>\n      {% if item.price_label %}\n        {% render 'snippets/product-card', product: item %}\n      {% else %}\n        {% render 'snippets/post-card', post: item, site: site %}\n      {% endif %}\n    </li>\n  {% else %}\n    <li class=\"empty\">Nothing is filed here yet.</li>\n  {% endfor %}\n</ul>\n\n{% render 'snippets/pagination', page: page %}\n",
}

/** The names, in the order a browser should show them. */
export const BASELINE_NAMES: string[] = Object.keys(BASELINE)
